"use client";
import { useEffect, useMemo, useState } from "react";
import { supabase } from "@/lib/supabase";

type Sticker = { id: string; name: string; rarity: string; image_url: string };
type Profile = { id: string; username: string; role: string; is_banned?: boolean };
type BoardRow = { username: string; total: number; legendary: number };
type ViewerRow = { username: string; sticker_id: string; sticker_name: string; rarity: string; image_url: string; collected_at: string };

export default function Home() {
  const [sessionUser, setSessionUser] = useState<any>(null);
    const [profile, setProfile] = useState<Profile | null>(null);
      const [username, setUsername] = useState("");
        const [password, setPassword] = useState("");
          const [isRegister, setIsRegister] = useState(true);
            const [message, setMessage] = useState("");
              const [busy, setBusy] = useState(false);
                const [lastDrop, setLastDrop] = useState<Sticker | null>(null);
                  const [spinning, setSpinning] = useState(false);
                    const [board, setBoard] = useState<BoardRow[]>([]);
                      const [inventory, setInventory] = useState<Sticker[]>([]);
                        const [pity, setPity] = useState(0);
                          const [hdBalance, setHdBalance] = useState(0);
  const [odds, setOdds] = useState({ rare: "65.5", epic: "33.3", legendary: "1", secret: "0.2" });
  const [oddsMode, setOddsMode] = useState("own");
  const [oddsStatus, setOddsStatus] = useState("");
  const [oddsLoading, setOddsLoading] = useState(false);
  const [activeOdds, setActiveOdds] = useState({ rare: 65.5, epic: 33.3, legendary: 1, secret: 0.2 });
  const [customOddsActive, setCustomOddsActive] = useState(false);

                          const [viewerRows, setViewerRows] = useState<ViewerRow[]>([]);
                            const [viewerStickers, setViewerStickers] = useState<Sticker[]>([]);
                              const [selectedViewer, setSelectedViewer] = useState("");
                                const [viewerLoading, setViewerLoading] = useState(false);
                                  const [viewerMessage, setViewerMessage] = useState("");

                                    async function handleBannedAccount() {
                                        await supabase.auth.signOut({ scope: "local" });
                                            setSessionUser(null);
                                                setProfile(null);
                                                    setInventory([]);
                                                        setLastDrop(null);
                                                            setPity(0);
                                                                setHdBalance(0);
                                                                setViewerRows([]);
                                                                    setViewerStickers([]);
                                                                        setSelectedViewer("");
                                                                            setMessage("This account has been banned. You have been signed out. Contact an Admin if you think this is a mistake.");
                                                                              }

                                                                                async function checkBanStatus() {
                                                                                    const { data: auth, error: authError } = await supabase.auth.getUser();
                                                                                        if (authError || !auth.user) return;

                                                                                            const { data, error } = await supabase
                                                                                                  .from("profiles")
                                                                                                        .select("is_banned")
                                                                                                              .eq("id", auth.user.id)
                                                                                                                    .maybeSingle();

                                                                                                                        if (!error && data?.is_banned === true) {
                                                                                                                              await handleBannedAccount();
                                                                                                                                  }
                                                                                                                                    }

                                                                                                                                      async function loadViewer() {
                                                                                                                                          setViewerLoading(true); setViewerMessage("");
                                                                                                                                              const [{ data: rows, error: rowsError }, { data: stickers, error: stickersError }] = await Promise.all([
                                                                                                                                                    supabase.rpc("viewer_list_collections"), supabase.rpc("viewer_list_stickers")
                                                                                                                                                        ]);
                                                                                                                                                            if (rowsError || stickersError) {
                                                                                                                                                                  setViewerMessage(rowsError?.message || stickersError?.message || "Could not load viewer.");
                                                                                                                                                                        setViewerRows([]); setViewerStickers([]);
                                                                                                                                                                            } else {
                                                                                                                                                                                  const safeRows = (rows || []) as ViewerRow[];
                                                                                                                                                                                        setViewerRows(safeRows); setViewerStickers((stickers || []) as Sticker[]);
                                                                                                                                                                                              setSelectedViewer(current => current || safeRows[0]?.username || "");
                                                                                                                                                                                                  }
                                                                                                                                                                                                      setViewerLoading(false);
                                                                                                                                                                                                        }

                                                                                                                                                                                                          async function loadProfile(userId: string) {
                                                                                                                                                                                                              const { data } = await supabase.from("profiles").select("id,username,role,is_banned").eq("id", userId).single();
                                                                                                                                                                                                                  if (data?.is_banned === true) {
                                                                                                                                                                                                                        await handleBannedAccount();
                                                                                                                                                                                                                              return null;
                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                      if (data) {
                                                                                                                                                                                                                                            setProfile(data); setUsername(data.username);
                                                                                                                                                                                                                                                  if (data.role === "admin" || data.role === "tester") { await loadViewer(); }
                                                                                                                                                                                                                                                        else { setViewerRows([]); setViewerStickers([]); setSelectedViewer(""); }
                                                                                                                                                                                                                                                              return data as Profile;
                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                      return null;
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                          async function refresh() {
                                                                                                                                                                                                                                                                              const { data: auth } = await supabase.auth.getUser();
                                                                                                                                                                                                                                                                                  if (!auth.user) {
                                                                                                                                                                                                                                                                                        setSessionUser(null); setProfile(null); setViewerRows([]); setViewerStickers([]); setSelectedViewer(""); setHdBalance(0); return;
                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                setSessionUser(auth.user);
                                                                                                                                                                                                                                                                                                    const loadedProfile = await loadProfile(auth.user.id);
                                                                                                                                                                                                                                                                                                        if (!loadedProfile) return;
                                            await loadMyOdds(loadedProfile.role);
                                                                                                                                                                                                                                                                                                            const [{ data: inv }, { data: stats }] = await Promise.all([
                                                                                                                                                                                                                                                                                                                  supabase.from("collections").select("stickers(id,name,rarity,image_url)").eq("user_id", auth.user.id).order("created_at", { ascending: false }),
                                                                                                                                                                                                                                                                                                                        supabase.from("profiles").select("pity_count,hd_balance").eq("id", auth.user.id).single()
                                                                                                                                                                                                                                                                                                                            ]);
                                                                                                                                                                                                                                                                                                                                setInventory((inv || []).map((x: any) => x.stickers).filter(Boolean));
                                                                                                                                                                                                                                                                                                                                    setPity(stats?.pity_count || 0);
                                                                                                                                                                                                     setHdBalance(stats?.hd_balance || 0);
                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                        async function loadMyOdds(role = profile?.role, mode = oddsMode) {
  const { data, error } = await supabase.rpc("get_my_spin_odds");
  if (error) { setOddsStatus(error.message); return; }
  const own = data?.own_odds;
  const global = data?.global_odds;
  const selected = role === "admin" && mode === "all" ? global : own;
  const effective = own || global;
  setCustomOddsActive(Boolean(effective));
  setActiveOdds(effective || { rare: 65.5, epic: 33.3, legendary: 1, secret: 0.2 });
  const values = selected || { rare: 65.5, epic: 33.3, legendary: 1, secret: 0.2 };
  setOdds({ rare: String(values.rare), epic: String(values.epic), legendary: String(values.legendary), secret: String(values.secret) });
}

async function saveMyOdds() {
  const values = { rare: Number(odds.rare), epic: Number(odds.epic), legendary: Number(odds.legendary), secret: Number(odds.secret) };
  if (Object.values(values).some(v => !Number.isFinite(v) || v < 0 || v > 100) || Math.round((values.rare + values.epic + values.legendary + values.secret) * 100) !== 10000) {
    setOddsStatus("Enter valid percentages that total exactly 100%."); return;
  }
  setOddsLoading(true); setOddsStatus("Saving…");
  const scope = profile?.role === "admin" ? oddsMode : "own";
  const { error } = await supabase.rpc("save_spin_odds", { target_scope: scope, new_odds: values });
  setOddsLoading(false);
  if (error) { setOddsStatus(error.message); return; }
  setOddsStatus(scope === "all" ? "Custom odds saved for all players." : "Your custom spin odds are saved.");
  await loadMyOdds(profile?.role, oddsMode);
}

async function resetMyOdds() {
  setOddsLoading(true); setOddsStatus("Resetting…");
  const scope = profile?.role === "admin" ? oddsMode : "own";
  const { error } = await supabase.rpc("reset_spin_odds", { target_scope: scope });
  setOddsLoading(false);
  if (error) { setOddsStatus(error.message); return; }
  setOddsStatus("Custom odds removed. Default odds are active.");
  await loadMyOdds(profile?.role, oddsMode);
  setOdds({ rare: "65.5", epic: "33.3", legendary: "1", secret: "0.2" });
}

async function refreshBoard() {
                                                                                                                                                                                                                                                                                                                                            const { data } = await supabase.from("leaderboard").select("username,total,legendary").order("total", { ascending: false }).limit(25);
                                                                                                                                                                                                                                                                                                                                                setBoard((data || []) as BoardRow[]);
                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                    useEffect(() => {
                                                                                                                                                                                                                                                                                                                                                        supabase.auth.getSession().then(({ data }) => {
                                                                                                                                                                                                                                                                                                                                                              if (data.session?.user) { setSessionUser(data.session.user); void refresh(); }
                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                      void refreshBoard();
                                                                                                                                                                                                                                                                                                                                                                          const channel = supabase.channel("leaderboard-live").on("postgres_changes", { event: "*", schema: "public", table: "collections" }, refreshBoard).subscribe();
                                                                                                                                                                                                                                                                                                                                                                              const timer = setInterval(refreshBoard, 12000);
                                                                                                                                                                                                                                                                                                                                                                                  // Check the profile's ban flag frequently so an already-open game signs out promptly.
                                                                                                                                                                                                                                                                                                                                                                                      const banTimer = setInterval(() => { void checkBanStatus(); }, 5000);
                                                                                                                                                                                                                                                                                                                                                                                          return () => { supabase.removeChannel(channel); clearInterval(timer); clearInterval(banTimer); };
                                                                                                                                                                                                                                                                                                                                                                                            }, []);

                                                                                                                                                                                                                                                                                                                                                                                              async function authenticate() {
                                                                                                                                                                                                                                                                                                                                                                                                  setBusy(true); setMessage("");
                                                                                                                                                                                                                                                                                                                                                                                                      const clean = username.trim().toLowerCase();
                                                                                                                                                                                                                                                                                                                                                                                                          if (!/^[a-z0-9_]{3,18}$/.test(clean)) { setMessage("Username must be 3–18 characters: letters, numbers or underscore."); setBusy(false); return; }
                                                                                                                                                                                                                                                                                                                                                                                                              const email = `${clean}@login.stickerrush.com`;
                                                                                                                                                                                                                                                                                                                                                                                                                  const result = isRegister
                                                                                                                                                                                                                                                                                                                                                                                                                        ? await supabase.auth.signUp({ email, password, options: { data: { username: clean } } })
                                                                                                                                                                                                                                                                                                                                                                                                                              : await supabase.auth.signInWithPassword({ email, password });
                                                                                                                                                                                                                                                                                                                                                                                                                                  if (result.error) setMessage(result.error.message);
                                                                                                                                                                                                                                                                                                                                                                                                                                      else if (result.data.user) {
                                                                                                                                                                                                                                                                                                                                                                                                                                            setSessionUser(result.data.user);
                                                                                                                                                                                                                                                                                                                                                                                                                                                  await loadProfile(result.data.user.id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                        const { data: currentSession } = await supabase.auth.getSession();
                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!currentSession.session) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      setBusy(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setMessage(isRegister ? "Account created! Welcome to Sticker Rush." : "Welcome back!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await refresh();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setBusy(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            async function spin() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (busy || spinning) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setBusy(true); setSpinning(true); setLastDrop(null); setMessage("");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const { data, error } = await supabase.rpc("spin_sticker");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (error) { setMessage(error.message); setSpinning(false); setBusy(false); return; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const result = data as any;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setTimeout(async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setLastDrop(result.sticker); setPity(result.pity_count);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await refresh(); await refreshBoard(); setSpinning(false); setBusy(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }, 2300);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        async function logout() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            await supabase.auth.signOut(); setSessionUser(null); setProfile(null); setInventory([]); setLastDrop(null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                setViewerRows([]); setViewerStickers([]); setSelectedViewer("");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const next = pity >= 49 ? "5% SECRET · 95% LEGENDARY" : (pity + 1) % 10 === 0 ? "MILESTONE: 60% RARE · 30% EPIC · 10% LEGENDARY" : `${50 - pity} spins until guarantee`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const counts = useMemo(() => ({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          rare: inventory.filter(s => s.rarity === "rare").length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              epic: inventory.filter(s => s.rarity === "epic").length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  legendary: inventory.filter(s => s.rarity === "legendary").length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           secret: inventory.filter(s => s.rarity === "secret").length
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }), [inventory]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const viewerPlayers = useMemo(() => Array.from(new Set(viewerRows.map(row => row.username))).sort((a,b) => a.localeCompare(b)), [viewerRows]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const selectedRows = useMemo(() => viewerRows.filter(row => row.username === selectedViewer), [viewerRows, selectedViewer]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const canView = profile?.role === "admin" || profile?.role === "tester";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return <main className="shell">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <header className="top"><a className="brand" href="#">✦ STICKER RUSH</a><span className="live">● LIVE GAME</span></header>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {!sessionUser ? <section className="auth panel">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="eyebrow">THE STICKER SUMMONING GAME</div><h1>Spin for<br/><span>something legendary.</span></h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="muted">Create a username, spin the wheel and climb the global leaderboard.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="tabs"><button className={isRegister ? "selected" : ""} onClick={() => setIsRegister(true)}>Create account</button><button className={!isRegister ? "selected" : ""} onClick={() => setIsRegister(false)}>Log in</button></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <label>USERNAME</label><input value={username} onChange={e => setUsername(e.target.value)} placeholder="e.g. shadow_07" maxLength={18}/>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <label>PASSWORD</label><input type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="At least 8 characters" onKeyDown={e => e.key === "Enter" && authenticate()}/>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button className="primary full" disabled={busy || password.length < 8} onClick={authenticate}>{busy ? "PLEASE WAIT…" : isRegister ? "CREATE PLAYER ACCOUNT →" : "LOG IN →"}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {message && <p className="notice">{message}</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p className="tiny">Username is public on the leaderboard. Never reuse an important password.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </section> : <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <section className="welcome"><div><div className="eyebrow">WELCOME BACK</div><h1>{profile?.username || username}</h1><p className="muted">Your collection is waiting.</p></div><div className="actions"><span className="hdBalance">💎 {hdBalance.toLocaleString()} HD</span>{profile?.role === "admin" && <a className="adminLink" href="/admin">ADMIN PANEL ↗</a>}<button className="ghost" onClick={logout}>LOG OUT</button></div></section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <section className="gameGrid">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="panel wheelPanel">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="eyebrow">THE SUMMONING WHEEL</div><h2>One spin. One sticker.</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className={`wheel ${spinning ? "animate" : ""}`}><div className="wheelInner"><span>✦</span><b>{spinning ? "SUMMONING" : "SPIN"}</b><small>YOUR LUCK AWAITS</small></div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="odds">{(["rare","epic","legendary","secret"] as const).map(key => <span key={key}>{key === "rare" ? "⚪" : key === "epic" ? "🟣" : key === "legendary" ? "🟡" : "💜"} {key.toUpperCase()} <b>{customOddsActive ? `${activeOdds[key]}%` : pity >= 49 ? (key === "secret" ? "5%" : key === "legendary" ? "95%" : "0%") : (pity + 1) % 10 === 0 ? ({rare:"60%",epic:"30%",legendary:"10%",secret:"0%"}[key]) : ({rare:"65.5%",epic:"33.3%",legendary:"1%",secret:"0.2%"}[key])}</b></span>)}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button className="primary full spinButton" disabled={busy || inventory.length < 0} onClick={spin}>{spinning ? "THE WHEEL IS TURNING…" : "✦ SPIN NOW"}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="pity"><span>{customOddsActive ? "CUSTOM ODDS ACTIVE · PITY PAUSED" : "LEGENDARY / SECRET PITY"}</span><b>{pity}/50</b><div className="bar"><i style={{width: `${Math.min(100,pity*2)}%`}}/></div><small>{next}</small></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {message && <p className="notice">{message}</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="side">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="panel reveal"><div className="eyebrow">LATEST DROP</div>{lastDrop ? <div className={`drop ${lastDrop.rarity}`}><img src={lastDrop.image_url} alt={lastDrop.name}/><h2>{lastDrop.name}</h2><span>{lastDrop.rarity.toUpperCase()}</span></div> : <div className="emptyDrop">✧<p>Your next sticker reveal appears here.</p></div>}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="panel"><div className="eyebrow">YOUR COLLECTION</div><div className="stats"><div><b>{inventory.length}</b><span>TOTAL</span></div><div><b>{counts.rare}</b><span>RARE</span></div><div><b>{counts.epic}</b><span>EPIC</span></div><div><b>{counts.legendary}</b><span>LEGENDARY</span></div><div><b>{counts.secret}</b><span>SECRET</span></div></div><div className="miniInventory">{inventory.slice(0,8).map((s,i)=><img key={i} src={s.image_url} title={`${s.name} (${s.rarity})`} alt={s.name}/>)}</div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </section>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {(profile?.role === "admin" || profile?.role === "tester") && <section className="panel" style={{marginTop:24}}>
  <div className="eyebrow">{profile.role === "admin" ? "ADMIN CONTROL" : "TESTER TOOLS"}</div>
  <h2>🎯 Spin Odds Control</h2>
  <p className="muted">Custom odds replace normal, milestone and pity odds while enabled.</p>
  {profile.role === "admin" && <label>APPLY CUSTOM ODDS TO
    <select value={oddsMode} onChange={e => { setOddsMode(e.target.value); void loadMyOdds(profile?.role, e.target.value); }} style={{display:"block",width:"100%",maxWidth:360,margin:"8px 0 16px",padding:12,borderRadius:10}}>
      <option value="own">Own Spins</option><option value="all">All Players</option>
    </select>
  </label>}
  <div className="formGrid">
    {(["rare","epic","legendary","secret"] as const).map(key => <label key={key}>{key.toUpperCase()} CHANCE (%)
      <input type="number" min="0" max="100" step="0.1" value={odds[key]} onChange={e => setOdds(current => ({...current,[key]:e.target.value}))}/>
    </label>)}
  </div>
  <p className="muted">Total: {(Number(odds.rare)+Number(odds.epic)+Number(odds.legendary)+Number(odds.secret)).toFixed(2)}% · Must equal 100%</p>
  <button className="primary" onClick={saveMyOdds} disabled={oddsLoading}>{oddsLoading ? "PLEASE WAIT…" : "SAVE ODDS"}</button>
  <button className="ghost" onClick={resetMyOdds} disabled={oddsLoading} style={{marginLeft:8}}>RESET TO DEFAULT</button>
  {oddsStatus && <p className="notice">{oddsStatus}</p>}
  <p className="tiny">{profile.role === "tester" ? "These settings affect only your own spins." : oddsMode === "all" ? "These settings affect every player's spins, unless that player has their own custom odds." : "These settings affect only your own spins."}</p>
</section>}

{canView && <section className="panel" style={{marginTop:24}}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="leaderHead"><div><div className="eyebrow">READ-ONLY ACCESS · {profile?.role.toUpperCase()}</div><h2>🔎 Collection Viewer</h2><p className="muted">Browse player collections and the full sticker catalogue. Viewing only — no spin, edit or delete controls.</p></div><button className="ghost" onClick={loadViewer} disabled={viewerLoading}>{viewerLoading ? "LOADING…" : "↻ REFRESH"}</button></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {viewerMessage && <p className="notice">{viewerMessage}</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {viewerLoading && <p className="muted">Loading collections and stickers…</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {!viewerLoading && <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h3>PLAYER COLLECTIONS</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {viewerPlayers.length ? <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <label htmlFor="viewer-player">SELECT A PLAYER</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <select id="viewer-player" value={selectedViewer} onChange={e => setSelectedViewer(e.target.value)} style={{display:"block",width:"100%",maxWidth:420,margin:"10px 0 18px",padding:12,borderRadius:10}}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {viewerPlayers.map(player => <option key={player} value={player}>{player}</option>)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="muted">{selectedRows.length} collected sticker{selectedRows.length === 1 ? "" : "s"} for {selectedViewer}.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {selectedRows.length ? <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(125px,1fr))",gap:12}}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {selectedRows.map((row,index) => <div className={`drop ${row.rarity}`} key={`${row.sticker_id}-${index}`} style={{padding:10,borderRadius:12,textAlign:"center"}}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <img src={row.image_url} alt={row.sticker_name} style={{width:"100%",maxWidth:130,aspectRatio:"1/1",objectFit:"contain"}}/><b>{row.sticker_name}</b><div><small>{row.rarity.toUpperCase()}</small></div><small>{new Date(row.collected_at).toLocaleDateString()}</small>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div> : <p className="muted">This player has not collected any stickers yet.</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </> : <p className="muted">No player collections yet.</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div style={{marginTop:28}}><div className="eyebrow">COMPLETE STICKER CATALOGUE</div><h3>ALL STICKERS ({viewerStickers.length})</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {viewerStickers.length ? <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(125px,1fr))",gap:12}}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {viewerStickers.map(sticker => <div className={`drop ${sticker.rarity}`} key={sticker.id} style={{padding:10,borderRadius:12,textAlign:"center"}}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <img src={sticker.image_url} alt={sticker.name} style={{width:"100%",maxWidth:130,aspectRatio:"1/1",objectFit:"contain"}}/><b>{sticker.name}</b><div><small>{sticker.rarity.toUpperCase()}</small></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div> : <p className="muted">No stickers are in the catalogue yet.</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </section>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <section className="panel leaderboard"><div className="leaderHead"><div><div className="eyebrow">THE GLOBAL RANKINGS</div><h2>🏆 Top collectors</h2></div><span className="live">● UPDATING LIVE</span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {board.length ? <div className="board">{board.map((p,i)=><div className="boardRow" key={p.username}><span className="rank">{String(i+1).padStart(2,"0")}</span><b>{p.username}</b><span className="legendCount">✦ {p.legendary} legendary</span><strong>{p.total} <small>stickers</small></strong></div>)}</div> : <p className="muted">The leaderboard will appear when the first players collect stickers.</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <footer>STICKER RUSH <span>SPIN • COLLECT • DOMINATE</span></footer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </main>;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              